WITH store_sales_by_product AS (SELECT product_id, MIN(units) AS min_units, MAX(units) AS max_units FROM store_sales WHERE store_id IN (2, 3) GROUP BY product_id) SELECT products.launch_date, store_sales_by_product.min_units, store_sales_by_product.max_units FROM products LEFT JOIN store_sales_by_product ON products.id = store_sales_by_product.product_id WHERE store_sales_by_product.max_units > 18 ORDER BY store_sales_by_product.min_units;
